#import <Cocoa/Cocoa.h>
int main(void){@autoreleasepool{NSApplication *app=[NSApplication sharedApplication];[app setActivationPolicy:NSApplicationActivationPolicyAccessory];NSOpenPanel *panel=[NSOpenPanel openPanel];panel.title=@"Choose where FWRD.STUDIO saves media";panel.message=@"New media will be saved in a FWRD.STUDIO Media subfolder. Existing files will stay where they are.";panel.prompt=@"Use this folder";panel.canChooseFiles=NO;panel.canChooseDirectories=YES;panel.canCreateDirectories=YES;panel.allowsMultipleSelection=NO;[app activateIgnoringOtherApps:YES];if([panel runModal]!=NSModalResponseOK)return 2;printf("%s\n",panel.URL.path.fileSystemRepresentation);return 0;}}
